select lbl, (allowlisted and not excluded) kept, count(*) n_pool, bool_or(allow_v1 and not excluded) v1_kept,
  min(inc_ids[1]) rule, bool_or(allowlisted and not allow_label) loinc_only, bool_or(excluded) db_excl
from dk where encref is not null and dl_ok group by 1,2 order by 2, 3 desc;

