    bool_or(f_selectable_shipped and dl_ok) keep_dl,
    bool_or(f_selectable_now and allow_v1) keep_v1,
    bool_or(f_selectable_now and allow_alt_no_tel) keep_no_tel,
    bool_or(f_selectable_now and allow_alt_no_op) keep_no_op,
    bool_or(f_selectable_now and allow_alt_no_tel_no_op) keep_no_tel_no_op,
    bool_or(f_selectable_now and allow_alt_no_code) keep_no_code,
    bool_or(f_selectable_now and not allowlisted) has_nonallow,
    bool_or(f_selectable_now) any_now
  from dk where encref is not null group by 1,2),
appt_s as (
  select a.id, a.created_at appt_created, e.*, s.outcome, s.upd, s.src_allow, s.src_nonallow
  from appointments a
  join enc_flags e on e.user_id=a.user_id and e.encref = 'Encounter/'||replace(a.ehr_entity_id,'Encounter/','')
  cross join lateral (
    select case when cs.metadata::jsonb->>'processing_outcome' is not null then cs.metadata::jsonb->>'processing_outcome'
                when coalesce((cs.metadata::jsonb->>'successful_documents')::int,0)>0 then 'legacy-success'
                else 'legacy-nodocs' end outcome,
      cs.updated_at upd,
      (select count(*) from jsonb_array_elements(case when jsonb_typeof(cs.metadata::jsonb->'document_metadata')='array'
            then cs.metadata::jsonb->'document_metadata' else '[]'::jsonb end) m
        where coalesce(exists (select 1 from allow_rules r where r.kind='include' and lower(btrim(regexp_replace(m->>'clinical_document_type', '[ \t\r\n\f\v ]+', ' ', 'g'))) ~ r.pattern),false)
          and not coalesce(exists (select 1 from allow_rules r where r.kind='deny' and lower(btrim(regexp_replace(m->>'clinical_document_type', '[ \t\r\n\f\v ]+', ' ', 'g'))) ~ r.pattern),false)) src_allow,
      (select count(*) from jsonb_array_elements(case when jsonb_typeof(cs.metadata::jsonb->'document_metadata')='array'
            then cs.metadata::jsonb->'document_metadata' else '[]'::jsonb end) m
        where not (coalesce(exists (select 1 from allow_rules r where r.kind='include' and lower(btrim(regexp_replace(m->>'clinical_document_type', '[ \t\r\n\f\v ]+', ' ', 'g'))) ~ r.pattern),false)
          and not coalesce(exists (select 1 from allow_rules r where r.kind='deny' and lower(btrim(regexp_replace(m->>'clinical_document_type', '[ \t\r\n\f\v ]+', ' ', 'g'))) ~ r.pattern),false))) src_nonallow
    from conversation_summaries cs
    where cs.appointment_id=a.id and cs.metadata::jsonb->>'source'='attachment_summary'
    order by cs.updated_at desc limit 1) s
  where a.ehr_entity_id is not null)
select coalesce(prov,'ALL') prov, coalesce(outcome,'ALL') outcome, count(*) appts,
  count(*) filter (where keep_f) keep_v2, count(*) filter (where not keep_f) lose_v2,
  count(*) filter (where not keep_v1) lose_v1, count(*) filter (where not keep_no_tel) lose_alt_no_tel,
  count(*) filter (where not keep_no_op) lose_alt_no_op, count(*) filter (where not keep_no_tel_no_op) lose_alt_no_tel_no_op,
  count(*) filter (where not keep_no_code) lose_alt_no_loinc,
  count(*) filter (where keep_f and has_nonallow) keep_but_selection_changes,
  count(*) filter (where keep_f and src_allow>0) keep_and_latest_had_allowlisted_src,
  count(*) filter (where src_nonallow>0 and src_allow>0) summary_src_mixed, count(*) filter (where src_nonallow>0 and src_allow=0) summary_src_no_allowlisted
from appt_s where upd > now() - interval '60 days' group by rollup(prov, outcome) order by 1,2;

