  -- one detoast per row: jsonb_to_record extracts every key at once
  select f.user_id, f.ehr_provider::text prov, r."encounterReference" encref,
    lower(btrim(regexp_replace(r.type, '[ \t\r\n\f\v ]+', ' ', 'g'))) lbl,
    r.type raw_type, r."typeCode" tc, r."typeSystem" ts,
    coalesce(r."isProcedureDocument",'null') ipd,
    coalesce(jsonb_typeof(r.attachments)='array' and jsonb_array_length(r.attachments)>0, false) att_ok,
    coalesce(r.attachments @> '[{"downloadStatus":"success"}]'::jsonb, false) dl_ok,
    coalesce(r."includeForSummary",'null') ifs,
