  from fhir_resources f cross join lateral jsonb_to_record(f.data) as r("encounterReference" text, type text, "typeCode" text,
    "typeSystem" text, "isProcedureDocument" text, "includeForSummary" text, attachments jsonb)
  where f.resource_type='DocumentReference'),
lx as materialized (
  select k, lbl, raw_type, tc, ts,
    coalesce(exists (select 1 from excl x where (x.strat='ilike' and raw_type ilike '%'||x.pat||'%')
                                            or (x.strat='exact' and raw_type = x.pat)), false) excluded,
    coalesce(array(select r.rule_id from allow_rules r where r.kind='include' and lbl ~ r.pattern order by 1), '{}') inc_ids,
    coalesce(exists (select 1 from allow_rules r where r.kind='deny' and lbl ~ r.pattern), false) denied,
    coalesce(tc in (select code from loinc_codes) and (ts ilike '%loinc%' or btrim(ts) = 'urn:oid:2.16.840.1.113883.6.1'), false) code_ok,
    coalesce(exists (select 1 from v1_rules r where r.kind='include' and lbl ~ r.pattern), false)
