  from fhir_resources e where e.resource_type='Encounter')
select case when tot >= 3 then etype else '(other n<3)' end etype, has_appt, other_allow, count(*) enc
from (select z.*, count(*) over (partition by etype) tot from (
      select t.*, coalesce(et.etype,'(no encounter row)') etype,
        exists (select 1 from appointments a where a.user_id=t.user_id and 'Encounter/'||replace(a.ehr_entity_id,'Encounter/','')=t.encref) has_appt
      from tel t left join et on et.user_id=t.user_id and et.encref=t.encref where t.has_tel) z) y
group by 1,2,3 order by 1,2,3;

