\echo ===R5_WRITES_BY_WEEK_120D (r4-f-03: conversation_summaries by source x outcome class)
select date_trunc('week', cs.updated_at)::date wk, coalesce(cs.metadata::jsonb->>'source','(none)') src,
  coalesce(cs.metadata::jsonb->>'processing_outcome', case when coalesce((cs.metadata::jsonb->>'successful_documents')::int,0)>0 then 'legacy-success' else 'legacy-nodocs' end) outcome,
  count(*) n
from conversation_summaries cs where cs.updated_at > now() - interval '120 days' group by 1,2,3 order by 1,2,3;
\echo ===R5_ACTIVITY_BY_WEEK_120D (appointments created [ehr-linked vs not], DocumentReference rows created, users active)
select wk, sum(appts_ehr) appts_ehr, sum(appts_other) appts_other, sum(docrefs) docrefs, sum(enc) encounters, sum(active_users) active_users from (
  select date_trunc('week', created_at)::date wk, count(*) filter (where ehr_entity_id is not null) appts_ehr, count(*) filter (where ehr_entity_id is null) appts_other, 0 docrefs, 0 enc, 0 active_users
    from appointments where created_at > now() - interval '120 days' group by 1
  union all select date_trunc('week', created_at)::date, 0,0, count(*) filter (where resource_type='DocumentReference'), count(*) filter (where resource_type='Encounter'), 0
    from fhir_resources where created_at > now() - interval '120 days' group by 1
  union all select date_trunc('week', last_active_at)::date, 0,0,0,0, count(*) from user_profiles where last_active_at > now() - interval '120 days' group by 1) z
group by 1 order by 1;
\echo ===R5_LAST_TIMESTAMPS
select (select max(updated_at)::date from conversation_summaries where metadata::jsonb->>'source'='attachment_summary') last_attachment_summary,
  (select max(created_at)::date from appointments where ehr_entity_id is not null) last_ehr_appt,
  (select max(created_at)::date from fhir_resources where resource_type='DocumentReference') last_docref,
  (select max(updated_at)::date from fhir_resources) last_fhir_update,
  (select max(last_active_at)::date from user_profiles) last_user_active;
\echo ===R5_EHR_APPTS_WITHOUT_ATTACHMENT_SUMMARY_BY_WEEK_120D
select date_trunc('week', a.created_at)::date wk, count(*) ehr_appts,
  count(*) filter (where not exists (select 1 from conversation_summaries cs where cs.appointment_id=a.id and cs.metadata::jsonb->>'source'='attachment_summary')) without_attachment_summary
from appointments a where a.ehr_entity_id is not null and a.created_at > now() - interval '120 days' group by 1 order by 1;
\echo ===R5_LEGACY_ROWS (r4-f-07)
select count(*) legacy_rows, count(*) filter (where coalesce((metadata::jsonb->>'successful_documents')::int,0)>0) legacy_success,
  min(updated_at)::date first, max(updated_at)::date last
from conversation_summaries where metadata::jsonb->>'source'='attachment_summary' and metadata::jsonb->>'processing_outcome' is null;

-- ===== EMR PART (run against care-capture-emr-<env>) =====

\echo ===R5_E_EXCLUDE_SET_MD5 (expect 36 / 70383e3c874bca92e2fbbe46dccda35e)
select count(*) n, md5(string_agg(match_value||'|'||match_strategy||'|'||source_emr, ',' order by match_value, match_strategy, source_emr)) set_md5
from document_type_rules where is_active and action='exclude';
\echo ===R5_E_RULES_BY_ACTION
select action, count(*) filter (where is_active) active, count(*) total from document_type_rules group by 1 order by 1;
\echo ===R5_E_CONNECTIONS (status + last sync week; no tokens/ids)
select coalesce(sync_status,'(null)') sync_status, is_active, sync_enabled, date_trunc('week', last_sync_at)::date last_sync_wk, count(*) n
from fhir_ehr_connections group by 1,2,3,4 order by 4 desc nulls last, 1;
